"""Genera las páginas estáticas. Ejecutar desde cualquier carpeta: python scripts/build.py."""
from pathlib import Path
import re, json, html
ROOT = Path(__file__).resolve().parents[1]
old = (ROOT/'originales/home.html').read_text(encoding='utf-8')
essay = (ROOT/'originales/ensayo.html').read_text(encoding='utf-8')
def take(pattern, text=old):
    return re.search(pattern,text,re.S).group(1)
bio_path=ROOT/'contenido/biografia.html'
essay_path=ROOT/'contenido/gobernar-la-ia.html'
if not bio_path.exists(): bio_path.write_text(take(r'<article class="col">(.*?)</article>').replace('<h2>Biografía</h2>',''),encoding='utf-8')
if not essay_path.exists(): essay_path.write_text(take(r'<article>(.*?)</article>',essay),encoding='utf-8')
sources_path=ROOT/'contenido/fuentes.html'
if not sources_path.exists(): sources_path.write_text(take(r'<section class="sources">(.*?)</section>',essay),encoding='utf-8')
posts_path=ROOT/'contenido/publicaciones.json'
if not posts_path.exists():
    posts_path.write_text(json.dumps([{'title':'Gobernar la IA o ser gobernados por ella','summary':'Por qué la abstención escolar no protege a los estudiantes: los entrega al default.','type':'Ensayos','topic':'IA y educación','date':'Octubre de 2026','minutes':12,'url':'ensayos/gobernar-la-ia.html','image':'ensayos/gobernar-la-ia.jpg'}],ensure_ascii=False,indent=2),encoding='utf-8')
posts=json.loads(posts_path.read_text(encoding='utf-8'))
press=take(r'<ul class="press">(.*?)</ul>')
talks=take(r'<ul class="talks">(.*?)</ul>')
awards=take(r'<ul class="awards">(.*?)</ul>')
bio_excerpt = re.search(r'<p>.*?</p>', bio_path.read_text(encoding='utf-8'), re.S).group(0)
bio_highlight = re.search(r'Es profesor de la Universidad de Buenos Aires,.*?Emprendedor21\.', bio_path.read_text(encoding='utf-8'), re.S).group(0)
def nav(active,prefix):
    items=[('Inicio','index.html'),('Sobre Pablo','sobre-pablo.html'),('Publicaciones','publicaciones.html'),('Charlas y prensa','charlas-prensa.html'),('Contacto','contacto.html')]
    links=''.join(f'<a href="{prefix}{url}"'+(' aria-current="page"' if active==name else '')+f'>{name}</a>' for name,url in items)
    return f'<a class="skip" href="#contenido">Saltar al contenido</a><header class="site-header"><div class="container header-inner"><a class="brand" href="{prefix}index.html">Pablo Aristizábal<span>Educación · Inteligencia artificial</span></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false">Menú</button><nav class="navigation" id="navigation" aria-label="Principal">{links}</nav></div></header>'
def footer(prefix):
    return f'<footer class="site-footer"><div class="container footer-inner"><span>© 2026 Pablo Aristizábal</span><a href="{prefix}contacto.html">Contacto ↗</a></div></footer>'
def page(file,title,body,active='Inicio',description='Educador, emprendedor tecnológico y ensayista. Fundador y CEO de FlexFlix.ai'):
    prefix='../' if '/' in file else ''
    doc=f'<!doctype html>\n<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Pablo Aristizábal</title><meta name="description" content="{html.escape(description,quote=True)}"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:type" content="{"article" if prefix else "website"}"><meta property="og:locale" content="es_AR"><meta name="theme-color" content="#182e30"><link rel="stylesheet" href="{prefix}assets/site.css"><link rel="stylesheet" href="{prefix}assets/editorial.css"><script src="{prefix}assets/vendor/gsap.min.js" defer></script><script src="{prefix}assets/vendor/ScrollTrigger.min.js" defer></script><script src="{prefix}assets/site.js" defer></script><script src="{prefix}assets/motion.js" defer></script></head><body class="{'home-page' if file == 'index.html' else 'inner-page'}">{nav(active,prefix)}<main id="contenido">{body}</main>{footer(prefix)}</body></html>'
    (ROOT/file).parent.mkdir(parents=True, exist_ok=True)
    (ROOT/file).write_text(doc,encoding='utf-8')
def card(post):
    p={k:html.escape(str(v),quote=True) for k,v in post.items()}
    return f'<article class="feature" data-post data-type="{p["type"]}" data-topic="{p["topic"]}"><a href="{p["url"]}" tabindex="-1" aria-hidden="true"><img src="{p["image"]}" alt="" loading="lazy"></a><div class="feature-copy"><p class="meta">{p["type"]} · {p["topic"]}</p><h3><a href="{p["url"]}">{p["title"]}</a></h3><p>{p["summary"]}</p><p class="meta">{p["date"]} · {p["minutes"]} min de lectura</p><a class="text-link" href="{p["url"]}">Leer {"noticia" if post["type"] == "Noticias" else "ensayo"} ↗</a></div></article>'
contact='<section class="contact-band"><div class="container contact-grid"><div><h2>Contacto</h2></div><a class="button" href="contacto.html">Contacto ↗</a></div></section>'
page('index.html','Pensar primero, IA después',f'''<section class="hero hero-full"><div class="hero-visual"><img src="header.jpg" alt="Pablo Aristizábal sentado a un escritorio, con libros, una laptop y un globo terráqueo luminoso de fondo" fetchpriority="high"></div><div class="container hero-content"><div class="hero-copy"><p class="eyebrow">Educación · Inteligencia artificial</p><h1>Pablo<br>Aristizábal</h1><p class="hero-motto">Pensar primero, <em>IA después.</em></p><p>Educador, emprendedor tecnológico y ensayista. Fundador y CEO de FlexFlix.ai</p><div class="actions"><a class="button" href="publicaciones.html">Ver publicaciones ↗</a><a class="text-link" href="sobre-pablo.html">Sobre Pablo</a></div></div><a class="hero-scroll" href="#ensayos">Publicaciones ↓</a></div></section><div class="container"><section class="section" id="ensayos"><div class="section-head"><div><p class="eyebrow">Ensayo destacado</p><h2>Publicaciones</h2></div><a class="text-link" href="publicaciones.html">Ver publicaciones ↗</a></div>{card(posts[0])}</section></div><section class="about-band"><div class="container"><div class="about-heading"><p class="eyebrow">Sobre Pablo</p><h2>Biografía</h2></div><div class="about-grid"><div><img class="about-portrait" src="assets/img/prensa-81.webp" alt="Pablo Aristizábal sentado en su oficina" loading="lazy"></div><div>{bio_excerpt}<p class="bio-highlight">{bio_highlight}</p><a class="button" href="sobre-pablo.html">Leer biografía ↗</a></div></div><div class="stats"><div><strong>~30 años</strong><span>construyendo educación digital en América Latina</span></div><div><strong>+150 M</strong><span>usuarios alcanzados por sus proyectos</span></div></div></div></section><div class="container"><section class="section"><div class="section-head"><div><p class="eyebrow">Entrevistas y artículos</p><h2>En prensa</h2></div><a class="text-link" href="charlas-prensa.html">Charlas y prensa ↗</a></div><ul class="press-list">{''.join(re.findall(r'<li>.*?</li>',press,re.S)[:3])}</ul></section></div>{contact}''')
page('sobre-pablo.html','Sobre Pablo',f'''<div class="container"><header class="page-intro"><p class="eyebrow">Sobre Pablo</p><h1>Biografía</h1><p>Educador, emprendedor tecnológico y ensayista. Fundador y CEO de FlexFlix.ai</p></header><div class="bio-layout"><article class="reading">{bio_path.read_text(encoding='utf-8')}</article><aside class="bio-aside"><img src="header.jpg" alt="Pablo Aristizábal en su escritorio"><div class="badge"><img src="time-2026.jpg" alt="TIME World's Top EdTech Companies 2026"><p>FlexFlix integra el ranking de TIME y Statista.</p></div></aside></div><section class="section"><p class="eyebrow">Trayectoria</p><h2>Reconocimientos</h2><p>Sus proyectos recibieron más de 20 premios nacionales e internacionales.</p><ul class="awards">{awards}</ul></section></div>{contact}''','Sobre Pablo')
page('publicaciones.html','Publicaciones',f'''<div class="container"><header class="page-intro"><p class="eyebrow">Ensayos y noticias</p><h1>Publicaciones</h1></header><section class="section" style="padding-top:15px"><div class="archive-tools"><div class="filters" aria-label="Filtrar publicaciones">{''.join(f'<button data-filter="{kind}" aria-pressed="{str(kind=="Todas").lower()}">{kind}</button>' for kind in ['Todas','Ensayos','Noticias','Premios'])}</div><input class="search" type="search" data-search placeholder="Buscar publicaciones…" aria-label="Buscar publicaciones"></div><p class="result-count" data-count aria-live="polite">{len(posts)} {"publicación" if len(posts) == 1 else "publicaciones"}</p><div>{''.join(card(post) for post in posts)}</div><p class="empty" data-empty hidden>No hay publicaciones para esta búsqueda. Probá con otro término o categoría.</p></section></div>''','Publicaciones')
page('charlas-prensa.html','Charlas y prensa',f'''<div class="container"><header class="page-intro"><p class="eyebrow">Conferencias y medios</p><h1>Charlas y prensa</h1></header><section class="section" style="padding-top:10px"><h2>En los medios</h2><ul class="press-list">{press}</ul></section><section class="section"><p class="eyebrow">Conferencias</p><h2>Temas de conferencia</h2><ul class="talks">{talks}</ul><div class="actions"><a class="button" href="contacto.html">Invitar a Pablo ↗</a></div></section></div>''','Charlas y prensa')
page('contacto.html','Contacto','''<div class="container"><header class="page-intro"><p class="eyebrow">Enlaces de contacto</p><h1>Contacto</h1></header><section class="section"><ul class="press-list"><li><span class="src">Contacto profesional</span><a href="https://www.linkedin.com/in/paristizabal/" target="_blank" rel="noopener">linkedin.com/in/paristizabal</a></li><li><span class="src">Educación y tecnología</span><a href="https://flexflix.ai" target="_blank" rel="noopener">flexflix.ai</a></li></ul></section></div>''','Contacto')
legacy_post = next(post for post in posts if post['url'] == 'ensayos/gobernar-la-ia.html')
for post in posts:
    if 'content' not in post:
        continue
    p = {key: html.escape(str(value), quote=True) for key, value in post.items()}
    body = (ROOT / post['content']).read_text(encoding='utf-8')
    sources = (ROOT / post['sources']).read_text(encoding='utf-8')
    image = '../' + post['image']
    original_link = f'<p><a href="{p["original"]}" target="_blank" rel="noopener">Ver original ↗</a></p>' if post.get('original') else ''
    page(post['url'], post['title'], f'''<div class="article-shell"><a class="text-link" href="../publicaciones.html">← Todas las publicaciones</a><header><p class="eyebrow" style="margin-top:35px">{"Noticia" if post["type"] == "Noticias" else "Ensayo"} · {p["topic"]}</p><h1>{p["title"]}</h1><p class="sub">{p["summary"]}</p><div class="byline"><span>{p["author"]}</span><span>{p["date"]}</span><span>{p["minutes"]} min de lectura</span></div></header><img class="article-image" src="{html.escape(image, quote=True)}" alt="{p["image_alt"]}"><article class="article-body">{body}</article><section class="sources">{sources}{original_link}</section><div class="share-tools"><button data-copy>Copiar enlace</button><button data-share hidden>Compartir</button><span class="share-status" role="status"></span></div></div>''', 'Publicaciones', post['summary'])
page('ensayos/gobernar-la-ia.html',legacy_post['title'],f'''<div class="article-shell"><a class="text-link" href="../publicaciones.html">← Todas las publicaciones</a><header><p class="eyebrow" style="margin-top:35px">Ensayo · IA y educación</p><h1>Gobernar la IA o ser <em>gobernados</em> por ella</h1><p class="sub">{legacy_post['summary']}</p><div class="byline"><span>Prof. Pablo Aristizábal</span><span>FlexFlix.ai</span><span>Octubre de 2026</span><span>12 min de lectura</span></div></header><img class="article-image" src="gobernar-la-ia.jpg" alt="A la izquierda, estudiantes frente a laptops de las que salen textos generados; a la derecha, un estudiante piensa junto a una docente que lo guía."><article class="article-body">{essay_path.read_text(encoding='utf-8')}</article><section class="sources">{sources_path.read_text(encoding='utf-8')}</section><div class="share-tools"><button data-copy>Copiar enlace</button><button data-share hidden>Compartir</button><span class="share-status" role="status"></span></div></div>''','Publicaciones',legacy_post['summary'])

print(f'Generadas {5 + len(posts)} páginas estáticas.')
